javascript:
(() => {
  const KEY='toadal:web:v1:feast-pass';
  const MIN_KEY='toadal:web:v1:companion-minimized';

  const navToggle=document.querySelector('.site-nav-toggle');
  const navLinks=document.getElementById('sitePrimaryLinks');
  if(navToggle&&navLinks){
    navToggle.addEventListener('click',()=>{
      const open=navToggle.getAttribute('aria-expanded')==='true';
      navToggle.setAttribute('aria-expanded',String(!open));
      navLinks.classList.toggle('is-open',!open);
    });
  }

  const defaults={schemaVersion:1,updatedAt:new Date().toISOString(),level:1,xp:0,sparks:0,treats:0,streak:{count:0,lastQualifiedPeriod:null}};
  let pass=defaults;
  try{
    const raw=localStorage.getItem(KEY);
    if(raw){
      const parsed=JSON.parse(raw);
      if(parsed&&parsed.schemaVersion===1) pass={...defaults,...parsed,streak:{...defaults.streak,...(parsed.streak||{})}};
    } else {
      localStorage.setItem(KEY,JSON.stringify(defaults));
    }
  }catch{}
  const setText=(sel,val)=>{const el=document.querySelector(sel);if(el)el.textContent=String(val)};
  setText('[data-pass-level]',Math.max(1,Number(pass.level)||1));
  setText('[data-pass-sparks]',Math.max(0,Number(pass.sparks)||0));
  setText('[data-pass-treats]',Math.max(0,Number(pass.treats)||0));
  setText('[data-pass-streak]',Math.max(0,Number(pass.streak?.count)||0));
  const progress=document.querySelector('[data-pass-progress]');
  const progressbar=progress?.parentElement;
  if(progress&&progressbar){
    const xp=Math.max(0,Number(pass.xp)||0);
    const pct=Math.min(100,xp%100);
    progress.style.width=pct+'%';
    progressbar.setAttribute('aria-valuenow',String(pct));
  }

  const companion=document.querySelector('[data-toadal-companion]');
  const companionText=companion?.querySelector('[data-companion-text]');
  const companionToggle=companion?.querySelector('.tf-companion-toggle');
  if(companion&&companionText&&companionToggle){
    let minimized=false;
    try{minimized=localStorage.getItem(MIN_KEY)==='1'}catch{}
    const apply=()=>{
      companion.classList.toggle('is-minimized',minimized);
      companionToggle.setAttribute('aria-expanded',String(!minimized));
      companionToggle.setAttribute('aria-label',minimized?'Expand Toadal companion':'Minimize Toadal companion');
      companionToggle.textContent=minimized?'+':'−';
    };
    apply();
    companionToggle.addEventListener('click',()=>{
      minimized=!minimized;
      try{localStorage.setItem(MIN_KEY,minimized?'1':'0')}catch{}
      apply();
    });
    const defaultMessage='Try a browser adventure!';
    let restoreTimer=0;
    const show=(message)=>{
      if(!message||minimized)return;
      companionText.textContent=message;
      clearTimeout(restoreTimer);
      restoreTimer=setTimeout(()=>{companionText.textContent=defaultMessage},4200);
    };
    document.querySelectorAll('[data-companion-message]').forEach(node=>{
      const msg=node.getAttribute('data-companion-message');
      node.addEventListener('pointerenter',()=>show(msg));
      node.addEventListener('focusin',()=>show(msg));
      node.addEventListener('touchstart',()=>show(msg),{passive:true});
    });
  }
})();
